from rank_bm25 import BM25Okapi

class BM25:
    def __init__(self, docs: list[str]):
        self.docs = docs
        self.bm25 = BM25Okapi([d.lower().split() for d in docs])

    def search(self, q: str, k: int = {{top_k}}):
        scores = self.bm25.get_scores(q.lower().split())
        order = sorted(range(len(scores)), key=lambda i: -scores[i])[:k]
        return [(self.docs[i], float(scores[i])) for i in order]

if __name__ == "__main__":
    b = BM25(["the cat sat", "a dog ran", "cats are cute"])
    print(b.search("cat"))
